function TokenBucket(options) {
    if (arguments.length > 0 && typeof options !== 'object') {
        throw new RangeError('Options must be an object');
    }

    const {
        capacity = options.capacity,
        refillPerSecond = options.refillPerSecond,
        now = options.now || Date.now
    } = options || {};

    // capacity validasyonu
    if (typeof capacity !== 'number' || !Number.isFinite(capacity) || capacity <= 0) {
        throw new RangeError('Capacity must be a positive finite number');
    }

    // refillPerSecond validasyonu
    if (typeof refillPerSecond !== 'number' || !Number.isFinite(refillPerSecond) || refillPerSecond < 0) {
        throw new RangeError('RefillPerSecond must be a non-negative finite number');
    }

    // internal state
    this._capacity = capacity;
    this._refillPerSecond = refillPerSecond;
    this._now = now;

    // timeSinceLastRefill: ilk çağrıldığında 0 olarak başlar
    this._timeSinceLastRefill = 0;

    // jeton sayısı: başlangıçta dolu
    this._tokens = capacity;
}

TokenBucket.prototype = {
    _refill() {
        const elapsed = this._now() - this._timeSinceLastRefill;
        if (elapsed <= 0) {
            return;
        }

        const secondsElapsed = elapsed / 1000;
        const newTokens = secondsElapsed * this._refillPerSecond;

        // Yeni jetonları ekle, ancak capacity'i aşma
        this._tokens = Math.min(this._capacity, this._tokens + newTokens);

        // Zamanı güncelle (ilk çağrıldakinden beri geçen süre)
        this._timeSinceLastRefill = this._now();
    },

    tryTake(n) {
        // n validasyonu
        if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
            throw new RangeError('n must be a positive finite number');
        }

        // Dolumu güncelle
        this._refill();

        // Yeterli jeton var mı?
        if (this._tokens >= n) {
            this._tokens -= n;
            return true;
        }
        return false;
    },

    available() {
        // Dolumu güncelle
        this._refill();
        return this._tokens;
    },

    msUntil(n) {
        // n validasyonu
        if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0) {
            throw new RangeError('n must be a positive finite number');
        }

        // Dolumu güncelle
        this._refill();

        // Eğer yeterli jeton varsa
        if (this._tokens >= n) {
            return 0;
        }

        // Gerekli jeton farkı
        const needed = n - this._tokens;

        // Dolum hızı 0 ise ve jeton yetmiyorsa
        if (this._refillPerSecond === 0) {
            return Infinity;
        }

        // Gerekli süre (saniye olarak)
        const secondsNeeded = needed / this._refillPerSecond;

        // Milisaniye olarak ve yukarı yuvarlanmış
        return Math.ceil(secondsNeeded * 1000);
    }
};

module.exports = { TokenBucket };

