const { TokenBucket } = require('./kova.js');

// Test 1: Temel kullanım
console.log('Test 1: Temel kullanım');
const tb = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log('available():', tb.available()); // 10
console.log('tryTake(5):', tb.tryTake(5)); // true
console.log('available():', tb.available()); // 5

// Test 2: Yetersiz jeton
console.log('\nTest 2: Yetersiz jeton');
const tb2 = new TokenBucket({ capacity: 5, refillPerSecond: 1 });
console.log('tryTake(10):', tb2.tryTake(10)); // false
console.log('available():', tb2.available()); // hala 5

// Test 3: msUntil
console.log('\nTest 3: msUntil');
const tb3 = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
tb3.tryTake(10); // 0 jeton kaldı
console.log('msUntil(5):', tb3.msUntil(5)); // 2500ms (2 jeton/s -> 2.5 saniye -> 2500ms, yukarı yuvarlandı)

// Test 4: Şimdilik yeterli
console.log('\nTest 4: Şimdilik yeterli');
const tb4 = new TokenBucket({ capacity: 10, refillPerSecond: 2 });
console.log('msUntil(5):', tb4.msUntil(5)); // 0 (10 >= 5)

// Test 5: Yavaş dolum
console.log('\nTest 5: Yavaş dolum');
const tb5 = new TokenBucket({ capacity: 10, refillPerSecond: 0.5 });
tb5.tryTake(10);
console.log('msUntil(5):', tb5.msUntil(5)); // 10000ms

// Test 6: Sahte now ile test
console.log('\nTest 6: Sahte now');
let callCount = 0;
const fakeNow = () => {
    callCount++;
    return 1000; // sabit 1000ms
};
const tb6 = new TokenBucket({ capacity: 10, refillPerSecond: 2, now: fakeNow });
console.log('available():', tb6.available()); // 10
tb6._refill(); // manuel çağır
console.log('msUntil(15):', tb6.msUntil(15)); // refillPerSecond > 0 olduğu için hesaplama yapmalı

// Test 7: capacity'a ulaşma
console.log('\nTest 7: capacity\'ye ulaşma');
const tb7 = new TokenBucket({ capacity: 10, refillPerSecond: 100 });
const savedNow = tb7._now;
tb7._now = () => savedNow() + 1000; // 1 saniye geçti
console.log('available():', tb7.available()); // 20 yerine 10 olmalı

// Test 8: RangeError testleri
console.log('\nTest 8: RangeError testleri');
try {
    new TokenBucket({ capacity: -1 });
} catch (e) {
    console.log('capacity < 0:', e.message);
}

try {
    new TokenBucket({ refillPerSecond: -1 });
} catch (e) {
    console.log('refillPerSecond < 0:', e.message);
}

try {
    new TokenBucket({ capacity: Infinity });
} catch (e) {
    console.log('capacity Infinity:', e.message);
}

try {
    new TokenBucket({ capacity: 5 });
    const tb8 = new TokenBucket({ capacity: 5 });
    tb8.tryTake(0);
} catch (e) {
    console.log('tryTake(0):', e.message);
}

try {
    new TokenBucket({ capacity: 5 });
    const tb9 = new TokenBucket({ capacity: 5 });
    tb9.msUntil(-1);
} catch (e) {
    console.log('msUntil(-1):', e.message);
}

// Test 9: Infinity refillPerSecond için
console.log('\nTest 9: refillPerSecond = 0');
const tb9 = new TokenBucket({ capacity: 10, refillPerSecond: 0 });
tb9.tryTake(10);
console.log('msUntil(5):', tb9.msUntil(5)); // Infinity

console.log('\nTüm testler tamamlandı!');
"

